use charlotte_protocol_kafka as wire;
use zeroize::Zeroizing;
mod support;
use support::observe;
fn fixture() -> wire::Profile<'static> {
    wire::Profile {
        instance_name: b"ZZZZZZZZ-instance",
        authority_endpoints: vec![wire::AuthorityEndpoint {
            service_name: b"kafka/ZZZZZZZZ",
            rights: wire::ALL_RIGHTS,
        }],
        endpoint_ipv4: [192, 0, 2, 1],
        host: b"kafka-1.test",
        port: 9093,
        broker_endpoints: vec![wire::BrokerEndpoint {
            endpoint_ipv4: [192, 0, 2, 2],
            host: b"kafka-2.test",
            port: 9094,
        }],
        tls: true,
        ca_certificate_der: b"ZZZZZZZZ-ca",
        topic: b"ZZZZZZZZ-events",
        partition: 0,
        produce_routes: vec![wire::ProduceRoute {
            topic: b"ZZZZZZZZ-output",
            partition: 1,
        }],
        max_produce_routes: 1,
        group: b"ZZZZZZZZ-group",
        transactional_id: b"ZZZZZZZZ-transaction",
        authentication: wire::Authentication::ScramSha256AndMtlsP256 {
            username: b"ZZZZZZZZ-user",
            password: b"ZZZZZZZZ-password",
            certificate_der: b"ZZZZZZZZ-certificate",
            private_key_der: b"ZZZZZZZZ-private-key",
        },
        rights: wire::ALL_RIGHTS,
        transaction_timeout_ms: 30_000,
    }
}

fn auth_offset(profile: &wire::Profile<'_>) -> usize {
    wire::PROFILE_HEADER_LEN
        + profile.instance_name.len()
        + profile.host.len()
        + profile.ca_certificate_der.len()
        + profile.topic.len()
        + profile.group.len()
        + profile.transactional_id.len()
}

fn credential_offsets(profile:&wire::Profile<'_>)->(usize,usize){
 let wire::Authentication::ScramSha256AndMtlsP256{username,password,certificate_der,..}=profile.authentication else{unreachable!()};
 let password_offset=auth_offset(profile)+username.len();(password_offset,password_offset+password.len()+certificate_der.len())
}
#[test]
fn encoded_password_release(){
 let p=fixture();let observed=observe(0,0,credential_offsets(&p).0,||drop(p.encode().unwrap()));
 assert!(observed.copy_erased,"password retained: {observed:?}");
}
#[test]
fn encoded_private_key_release(){
 let p=fixture();let observed=observe(0,0,credential_offsets(&p).1,||drop(p.encode().unwrap()));
 assert!(observed.copy_erased,"private key retained: {observed:?}");
}
#[test]
fn abandoned_password_release(){
 fn rejected(p:&wire::Profile<'_>)->Option<()>{let _encoded=p.encode().ok()?;None}
 let p=fixture();let observed=observe(0,0,credential_offsets(&p).0,||assert!(rejected(&p).is_none()));
 assert!(observed.copy_erased,"abandoned password retained: {observed:?}");
}
#[test]
fn existing_kernel_wrapper_erases(){
 let p=fixture();for offset in [credential_offsets(&p).0,credential_offsets(&p).1]{
 let observed=observe(0,0,offset,||drop(Zeroizing::new(p.encode().unwrap())));
 assert!(observed.copy_erased,"wrapped credentials retained: {observed:?}");
 assert_eq!(observed.allocations,1);assert_eq!(observed.growths,0);assert_eq!(observed.copy_releases,1);}
}
#[test]
fn debug_includes_both_credential_fields(){
 let p=fixture();let wire::Authentication::ScramSha256AndMtlsP256{password,private_key_der,..}=p.authentication else{unreachable!()};
 for rendered in [format!("{:?}",p),format!("{:?}",p.authentication)]{
 assert!(rendered.contains(&format!("password: {:?}",password)));
 assert!(rendered.contains(&format!("private_key_der: {:?}",private_key_der)));}
}

